import org.junit.jupiter.api.Test;

class ExpressionTripleReferenceRenderingTest {

	@Test
	void constructorsAndComponentExpressionsRoundTripNestedReferences() throws Exception {
		for (String expression : List.of("TRIPLE(<_:s>, <urn:p>, <<(<_:o> <urn:q> \"x\")>>)",
				"SUBJECT(TRIPLE(<_:s>, <urn:p>, <_:o>))", "PREDICATE(TRIPLE(<_:s>, <urn:p>, <_:o>))",
				"OBJECT(TRIPLE(<_:s>, <urn:p>, <_:o>))")) {
			String source = "SELECT (" + expression + " AS ?result) WHERE {}";
			var parsed = QueryParserUtil.parseQuery(QueryLanguage.SPARQL, source, null);
			BindingSet expected = evaluate(source);
			for (String rendered : List.of(new TupleExprIRRenderer().render(parsed.getTupleExpr()),
					new SPARQLQueryRenderer().render(parsed), new SparqlQueryRenderer().render(parsed))) {
				assertEquals(expected, evaluate(rendered), rendered);
			}
		}
	}

	@Test
	void experimentalRendererPreservesLabelledBnodeCallsWithinAnExpression() throws Exception {
		String source = "SELECT ?row ?same ?node WHERE { VALUES ?row { 1 2 } "
				+ "BIND(sameTerm(BNODE(\"label\"), BNODE(\"label\")) AS ?same) "
				+ "BIND(IF(?same, BNODE(\"label\"), BNODE(\"other\")) AS ?node) }";
		var parsed = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, source, null);
		String rendered = new SparqlQueryRenderer().render(parsed);
		List<BindingSet> sourceRows = evaluateRows(source);
		List<BindingSet> renderedRows = evaluateRows(rendered);

		assertEquals(sourceRows.size(), renderedRows.size(), rendered);
		assertEquals(2, renderedRows.size());
		for (int index = 0; index < renderedRows.size(); index++) {
			BindingSet row = renderedRows.get(index);
			assertEquals(sourceRows.get(index).getValue("row"), row.getValue("row"), rendered);
			assertEquals(sourceRows.get(index).getValue("same"), row.getValue("same"), rendered);
			assertTrue(((Literal) row.getValue("same")).booleanValue(), rendered);
			assertInstanceOf(BNode.class, row.getValue("node"));
		}
		assertNotEquals(renderedRows.get(0).getValue("node"), renderedRows.get(1).getValue("node"),
				"separate VALUES occurrences must retain distinct labelled BNODE identities after rendering");
	}

	@Test
	void legacyRendererPreservesFixedAndFreshBnodesAcrossRepeatedExecution() throws Exception {
		String source = "SELECT ?row ?fixed ?fresh ?same ?label WHERE { VALUES ?row { 1 2 } "
				+ "BIND(<_:fixed> AS ?fixed) BIND(BNODE() AS ?fresh) "
				+ "BIND(sameTerm(BNODE(\"x\"), BNODE(\"x\")) AS ?same) "
				+ "BIND(BNODE(\"x\") AS ?label) }";
		var parsed = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, source, null);
		String rendered = new SPARQLQueryRenderer().render(parsed);
		var renderedQuery = parseRendered(rendered);

		List<BindingSet> originalFirst = evaluateRows(parsed);
		List<BindingSet> renderedFirst = evaluateRows(renderedQuery);
		List<BindingSet> originalSecond = evaluateRows(parsed);
		List<BindingSet> renderedSecond = evaluateRows(renderedQuery);

		assertFixedFreshAndLabelledResults(originalFirst, "original first execution");
		assertFixedFreshAndLabelledResults(renderedFirst, rendered);
		assertFixedFreshAndLabelledResults(originalSecond, "original second execution");
		assertFixedFreshAndLabelledResults(renderedSecond, rendered);
		assertNotEquals(originalFirst.get(0).getValue("fresh"), originalSecond.get(0).getValue("fresh"));
		assertNotEquals(originalFirst.get(0).getValue("label"), originalSecond.get(0).getValue("label"));
		assertNotEquals(renderedFirst.get(0).getValue("fresh"), renderedSecond.get(0).getValue("fresh"), rendered);
		assertNotEquals(renderedFirst.get(0).getValue("label"), renderedSecond.get(0).getValue("label"), rendered);
	}

	private static ParsedQuery parseRendered(String rendered) {
		try {
			return QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, rendered, null);
		} catch (Exception e) {
			throw new AssertionError("The legacy renderer produced unparsable SPARQL:\n" + rendered, e);
		}
	}

	private static void assertFixedFreshAndLabelledResults(List<BindingSet> rows, String context) {
		assertEquals(2, rows.size(), context);
		for (BindingSet row : rows) {
			assertEquals(SimpleValueFactory.getInstance().createBNode("fixed"), row.getValue("fixed"), context);
			assertInstanceOf(BNode.class, row.getValue("fresh"), context);
			assertTrue(((Literal) row.getValue("same")).booleanValue(), context);
			assertInstanceOf(BNode.class, row.getValue("label"), context);
		}
		assertNotEquals(rows.get(0).getValue("fresh"), rows.get(1).getValue("fresh"), context);
		assertNotEquals(rows.get(0).getValue("label"), rows.get(1).getValue("label"), context);
	}

	private static BindingSet evaluate(String query) {
		return evaluateRows(query).get(0);
	}

	private static List<BindingSet> evaluateRows(String query) {
		var parsed = QueryParserUtil.parseQuery(QueryLanguage.SPARQL, query, null);
		return evaluateRows(parsed);
	}

	private static List<BindingSet> evaluateRows(ParsedQuery parsed) {
		ValueFactory valueFactory = new IdentityAwareValueFactory();
		TripleSource source = new TripleSource() {
			public ValueFactory getValueFactory() {
				return valueFactory;
			}

			public CloseableIteration<? extends Statement> getStatements(Resource s, IRI p, Value o,
					Resource... contexts) {
				return new EmptyIteration<>();
			}
		};
		List<BindingSet> result = new ArrayList<>();
		try (var rows = new DefaultEvaluationStrategy(source, null).precompile(parsed.getTupleExpr())
				.evaluate(EmptyBindingSet.getInstance())) {
			while (rows.hasNext()) {
				result.add(rows.next());
			}
		}
		return result;
	}

	private static final class IdentityAwareValueFactory extends SimpleValueFactory implements BNodeIdResolver {
		private final Set<String> knownIds = new HashSet<>();

		@Override
		public boolean hasBNodeId(String id) {
			return knownIds.contains(id);
		}

		@Override
		public BNode createBNode(String nodeID) {
			BNode bNode = super.createBNode(nodeID);
			knownIds.add(nodeID);
			return bNode;
		}
	}
}
